namespace SobhanNotificationHub.Services;public static class LoggingService{private static readonly object Gate=new();private static string PathName{get{var d=Path.Combine(AppSettings.DataDirectory,"logs");Directory.CreateDirectory(d);return Path.Combine(d,"app.log");}}public static void Info(string eventName,string? detail=null)=>Write("INFO",eventName,detail);public static void Error(string eventName,Exception? ex)=>Write("ERROR",eventName,ex is null?null:$"{ex.GetType().Name}: {Sanitize(ex.Message)}");private static void Write(string level,string name,string? detail){try{lock(Gate){File.AppendAllText(PathName,$"{DateTimeOffset.Now:O}\t{level}\t{name}\t{Sanitize(detail??"")}\n");}}catch{}}private static string Sanitize(string value){if(value.Length>1000)value=value[..1000];return value.Replace("device_token", "[secret]").Replace("X-Device-Token","[secret]");}}
